-- Paket ABT "abt-identitas-pihak-1nov" (1 Nov 2026, agen V; keputusan pengguna 101 dan 102): format identitas pihak putusan/penetapan = blangko acuan "[01] [Kabul Verstek] Cerai (Format Lengkap)".
-- Variabel 7047, 7048 dan fungsi isian_rtf_pihak_identitas, isian_rtf_pihak_tambahan diubah; blangko RTF lewat daftar-tambal.tsv/tambal.tsv. Hanya pengguna derry_briantono. Prasyarat: paket ke-30 (perbaikan-1nov) terpasang.
-- PERIKSA: tiap variabel persis isi paket; dua fungsi persis isi paket; variabel kalimat kuasa (8540 8541) dan relaas (9230 9231) tidak tersentuh; baris terakhir "SEMUA COCOK".
SELECT 'var 7047 diubah' AS butir, (SELECT COUNT(*) FROM abt_variabel WHERE (no_var=7047 AND MD5(nama)='64ef74b8b5dfba66d3be3b10a7c9692e' AND data_type='data_sql' AND MD5(sql_query)='94f40d4f4bd51b9fab75184521617176')) AS cocok;
SELECT 'var 7048 diubah' AS butir, (SELECT COUNT(*) FROM abt_variabel WHERE (no_var=7048 AND MD5(nama)='0d46332b5be50992e27dfcebf6ec1de4' AND data_type='data_sql' AND MD5(sql_query)='0424f2f0336893a1b4080e660d707361')) AS cocok;
SELECT 'fungsi identitas dan tambahan baru' AS butir, IF((SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND ((routine_name='isian_rtf_pihak_identitas' AND MD5(routine_definition)='5ec160298fe05aabdc4460ef1c58ff0e') OR (routine_name='isian_rtf_pihak_tambahan' AND MD5(routine_definition)='0737d6b33330c45da2597a8aa0755237'))) = 2, 1, 0) AS cocok;
SELECT 'variabel 7047 7048 hanya memanggil fungsi identitas' AS butir, IF((SELECT COUNT(*) FROM abt_variabel WHERE no_var IN (7047, 7048) AND sql_query LIKE '%%isian_rtf_pihak_identitas(%%' AND sql_query NOT LIKE '%%#0098#%%' AND sql_query NOT LIKE '%%#0335#%%') = 2, 1, 0) AS cocok;
SELECT IF((SELECT COUNT(*) FROM abt_variabel WHERE ((no_var=7047 AND MD5(nama)='64ef74b8b5dfba66d3be3b10a7c9692e' AND data_type='data_sql' AND MD5(sql_query)='94f40d4f4bd51b9fab75184521617176') OR (no_var=7048 AND MD5(nama)='0d46332b5be50992e27dfcebf6ec1de4' AND data_type='data_sql' AND MD5(sql_query)='0424f2f0336893a1b4080e660d707361'))) = 2 AND (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND ((routine_name='isian_rtf_pihak_identitas' AND MD5(routine_definition)='5ec160298fe05aabdc4460ef1c58ff0e') OR (routine_name='isian_rtf_pihak_tambahan' AND MD5(routine_definition)='0737d6b33330c45da2597a8aa0755237'))) = 2, 'SEMUA COCOK', 'TIDAK COCOK') AS hasil;
